import{z as o,x as s,o as l,c as d,q as A,j as i,D as e,d as B,s as n,S as r,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"KV 合并与蒸馏","description":"","frontmatter":{"title":"KV 合并与蒸馏","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kv-merge-distill.md","filePath":"llm/kv-merge-distill.md","lastUpdated":1791413859000}'),C={name:"llm/kv-merge-distill.md"};function p(m,E,D,h,c,f){const t=s("Mermaid");return l(),d("div",null,[E[2]||(E[2]=A('<h1 id="kv-合并与蒸馏" tabindex="-1">KV 合并与蒸馏 <a class="header-anchor" href="#kv-合并与蒸馏" aria-label="Permalink to &quot;KV 合并与蒸馏&quot;">​</a></h1><div class="epigraph"><p>驱逐问「扔掉谁」，合并问「谁能代表一组」；当冗余足够高，一条平均过的键比十条各留一半的键更便宜也更准。</p><footer>—— 据 Liu et al., MiniCache, 2024 的跨层融合与 Snell et al., 2022 的上下文蒸馏思路整理</footer></div><p><a href="/llm/kv-eviction-heuristics">上一课</a>的刀口是「扔掉谁」，估计器再好也救不了不可逆的误杀。本课换刀口：把多条压成一条。合并把冗余条目平均掉，蒸馏把压缩本身学进参数。两条路共同的赌注是：历史里存在可替代的自由度——驱逐假设低分条目没人看，合并假设一组条目能被它们的代表替换，蒸馏假设「压缩态 → 完整行为」这个映射可以被学会。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>历史往往冗余：重复的指令段、同义的相邻 token、逐层累加后高度相似的相邻层 KV。对这样的组，逐条驱逐反而危险——每一条都有小概率被注意到，删谁都是伤；而平均之后，组内方差才是误差，冗余越高误差越小。合并的直接障碍在键上：键带位置相位，注意力算的是 \\(q^\\top R_t k\\)，两条不同位置的键不能直接平均，相位混叠会破坏点积结构；值活在残差流语义下，可加可权，平均宽容得多。合并因此是一个「在哪个空间平均」的问题，而不是「平均会不会坏」的问题。</p><p><span class="marginnote">直觉类比：RoPE 相位像给每个位置的键盖了一枚「时间戳章」，注意力打分只认章对得上的配对。把两个不同时间戳的键直接平均，章就花了，谁也对不上——所以键要么只在位置相近的小窗口里合并，要么先「去章」平均完、再按代表位置重新盖章。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>跨 token 合并</strong>。相似 token 聚类（按键的余弦或按注意力行为），值加权平均；键必须限制在相对相位接近的窗口内合并，或先对键去相位、平均后再挂回代表位置的相位。适合指令重复、引用同一段落的长提示。</p><p><strong>跨层合并</strong>。残差流逐层累加，相邻层的 KV 相似度可以逼近 1，于是相邻层对可插值成一条，仅保留少量异质槽（汇点位置、高熵位置）的完整 KV——MiniCache 的结构就是这个形状：大部分层对融合，个别槽留全。要分清它与训练期共享的界限：<a href="/llm/cross-layer-kv-sharing">CLA</a> 与 <a href="/llm/yoco">YOCO</a> 把共享学进结构与权重，<a href="/llm/kv-as-long-context">推理期合并</a>是事后补偿，上限低于学出来的共享，但不要求重训。</p><p><strong>蒸馏</strong>。把压缩写进参数。<a href="/llm/activation-beacon">Activation Beacon</a> 插入信标 token，用它们的激活压缩前文，训练后把有效上下文从 4k 拉到 400k 量级；上下文蒸馏让学生模型在压缩状态下对齐完整上下文的行为分布。<a href="/llm/mla">MLA</a> 是同一思想的架构化终态：潜向量就是学出来的「合并」，满宽键值只是上投影的临时展开。</p>',10)),(l(),i(r,null,{default:e(()=>[n(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20KV%5B%22%E5%BE%85%E5%8E%8B%20KV%20%E7%BB%84%22%5D%20--%3E%20RED%7B%22%E5%86%97%E4%BD%99%E6%9D%A5%E8%87%AA%E5%93%AA%E4%B8%80%E7%BB%B4%22%7D%0A%20%20RED%20--%3E%7C%E7%9B%B8%E4%BC%BC%20token%7C%20TOK%5B%22%E8%81%9A%E7%B1%BB%EF%BC%8C%E5%90%8C%E7%9B%B8%E4%BD%8D%E5%86%85%E5%B9%B3%E5%9D%87%22%5D%0A%20%20RED%20--%3E%7C%E7%9B%B8%E9%82%BB%E5%B1%82%7C%20LAY%5B%22%E5%B1%82%E5%AF%B9%E6%8F%92%E5%80%BC%EF%BC%8C%E5%BC%82%E8%B4%A8%E6%A7%BD%E7%95%99%E5%85%A8%22%5D%0A%20%20RED%20--%3E%7C%E6%95%B4%E6%AE%B5%E5%8E%86%E5%8F%B2%7C%20DIST%5B%22%E8%92%B8%E9%A6%8F%EF%BC%9A%E4%BF%A1%E6%A0%87%20%2F%20%E6%BD%9C%E5%90%91%E9%87%8F%EF%BC%8C%E8%AE%AD%E7%BB%83%E6%89%80%E5%BE%97%22%5D%0A%20%20TOK%20--%3E%20EVAL%5B%22%E4%BB%BB%E5%8A%A1%E8%B4%A8%E9%87%8F%E9%AA%8C%E6%94%B6%22%5D%0A%20%20LAY%20--%3E%20EVAL%0A%20%20DIST%20--%3E%20EVAL%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"合并的误差模型是组内方差：\\(m\\) 条等权合并，误差与方差成正比，与冗余度互补。这解释了它与驱逐的分工——驱逐在分数低处下刀，合并在高冗余处下刀，最好的对象恰恰是「每条都被看过、但看的内容几乎一样」的组。跨层的可合并性来自残差流的累加结构：每层只写入一个小增量，邻近层的总量自然接近；假设在汇点与高熵槽失效，所以异质槽必须留全。蒸馏的机制是把推理期成本搬进训练期：一旦「压缩态」成为训练分布的一部分，模型学会从中恢复行为，服务时只付一次压缩写入的前向，不付逐 token 的账。",-1)),E[5]||(E[5]=a("p",null,"三刀的次序也由机制决定：先合并掉冗余（方差小、无感），再量化（噪声加在更少的条目上），最后驱逐（分数在更干净的缓存上统计）——反着做，驱逐会把本可合并的条目误杀。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"数字实例：把 4 条两两只差 1% 的相似键平均成 1 条，代表与任何一条的偏差仍在 1% 量级，几乎无感；若 4 条彼此差 30%，平均出的代表就谁都差得远。所以合并前先聚类「本来就像的」，而不是硬把不像的压成一条。")],-1)),(l(),i(r,null,{default:e(()=>[n(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E5%8E%9F%E5%A7%8B%20KV%20%E7%BB%84%3A%20%E5%86%97%E4%BD%99%E8%BF%98%E5%9C%A8%22%5D%20--%3E%20M%5B%22%E7%AC%AC%E4%B8%80%E5%88%80%3A%20%E5%90%88%E5%B9%B6%E5%86%97%E4%BD%99%E7%BB%84%22%5D%0A%20%20M%20--%3E%20M2%5B%22%E6%9D%A1%E7%9B%AE%E6%9B%B4%E5%B0%91%2C%20%E7%BB%84%E5%86%85%E6%96%B9%E5%B7%AE%E5%B0%8F%2C%20%E8%B4%A8%E9%87%8F%E5%87%A0%E4%B9%8E%E6%97%A0%E6%84%9F%22%5D%0A%20%20M2%20--%3E%20Q%5B%22%E7%AC%AC%E4%BA%8C%E5%88%80%3A%20%E9%87%8F%E5%8C%96%22%5D%0A%20%20Q%20--%3E%20Q2%5B%22%E9%87%8F%E5%8C%96%E5%99%AA%E5%A3%B0%E5%8A%A0%E5%9C%A8%E6%9B%B4%E5%B0%91%E7%9A%84%E6%9D%A1%E7%9B%AE%E4%B8%8A%22%5D%0A%20%20Q2%20--%3E%20E%5B%22%E7%AC%AC%E4%B8%89%E5%88%80%3A%20%E9%A9%B1%E9%80%90%22%5D%0A%20%20E%20--%3E%20E2%5B%22%E5%88%86%E6%95%B0%E5%9C%A8%E6%9B%B4%E5%B9%B2%E5%87%80%E7%9A%84%E7%BC%93%E5%AD%98%E4%B8%8A%E7%BB%9F%E8%AE%A1%2C%20%E8%AF%AF%E6%9D%80%E6%9B%B4%E5%B0%91%22%5D%0A%20%20E2%20-.%E5%8F%8D%E7%9D%80%E5%81%9A.-%3E%20X%5B%22%E5%85%88%E9%A9%B1%E9%80%90%3A%20%E6%8A%8A%E6%9C%AC%E5%8F%AF%E5%90%88%E5%B9%B6%E7%9A%84%E6%9D%A1%E7%9B%AE%E8%AF%AF%E6%9D%80%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=A('<p><span class="marginnote">合并与蒸馏都改变 KV 的「形状」：合并后的页 token 数与全量页不同，无法进同一条<a href="/llm/kv-prefix-cache">前缀共享链</a>；蒸馏产出的信标态则要求整条推理栈（模板、位置编码、缓存键）按新形状重写。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>推理期合并不可逆，与驱逐共享「时间错位」的失败模式；聚类与相位对齐的开销落在 prefill，长提示可摊、短请求不划算。跨层合并对「层增量异常大」的模型（深层仍在大幅改写表征）收益骤减。蒸馏需要训练数据与算力，分布漂移要重训，且压缩率是学出来的超参不是运行时旋钮。评估口径与驱逐相同：长上下文任务质量，不是困惑度；并把「合并组数、保留槽位、蒸馏压缩率」写进报告，否则数字无法复现。</p><p><span class="marginnote">常见误区：以为合并和改配置一样「随时可做、随时可撤」。推理期合并不可逆——被平均掉的条目拿不回来，和驱逐一样有时间错位的失败模式；上线前要像评测驱逐一样评测误杀，而不是只看省了多少显存。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>驱逐删自由度，合并以代表替换冗余组，蒸馏把压缩学进参数；误差模型分别是误杀、组内方差、分布漂移。</li><li>键合并不自由：RoPE 相位限制合并窗口或要求去相位；值可加，宽容得多。</li><li>相邻层 KV 高度相似是跨层融合的燃料，异质槽必须留全；上限是 CLA/YOCO 那类学出来的共享。</li><li>MLA、Beacon、上下文蒸馏同属「学出来的压缩」，训练成本换推理成本。</li><li>三刀次序：先合并、再量化、后驱逐；验收看长上下文任务。</li><li>出处：Liu et al., MiniCache, 2024；Snell et al., Learning by Distilling Context, 2022；架构口径据本仓库 MLA、CLA、Beacon 课。</li></ul>',6))])}const F=o(C,[["render",p]]);export{u as __pageData,F as default};
